'use client'
// Author: Dr Hamid MADANI drmdh@msn.com
import { ClientForm } from '@mostajs/secu/components/ClientForm'
import { useEffect, useState } from 'react'

export default function ClientsPage() {
  const [clients, setClients] = useState<any[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    fetch('/api/clients').then(r => r.json()).then(d => { setClients(d.data || []); setLoading(false) })
  }, [])

  if (loading) return <div className="p-6">Chargement...</div>

  return (
    <div className="p-6 space-y-4">
      <h1 className="text-2xl font-bold">Clients</h1>
      <div className="grid gap-4">
        {clients.map((c: any) => (
          <div key={c.id} className="p-4 border rounded">{c.firstName} {c.lastName} — {c.clientType}</div>
        ))}
      </div>
    </div>
  )
}

